#requires -Version 7.0
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'Initialize-TemporaryFiles.ps1')
$root=Join-Path $PSScriptRoot '../..'
$code=@"
using System;using System.IO;using System.Linq;using System.Collections.Generic;
public static class ThreadManager {public static bool IsMainThread()=>true;}
public enum StreamModeRead {Persistency}public enum StreamModeWrite {Persistency}
public class ItemValue {public int type;public Dictionary<string,string> Metadata;public ItemValue Clone()=>new ItemValue{type=type,Metadata=Metadata==null?null:new Dictionary<string,string>(Metadata)};public bool TryGetMetadata(string k,out string v){v=null;return Metadata!=null&&Metadata.TryGetValue(k,out v);}public void SetMetadata(string k,string v){if(Metadata==null)Metadata=new Dictionary<string,string>();Metadata[k]=v;}}
public class ItemStack {public ItemValue itemValue;public int count;public ItemStack(ItemValue v,int n){itemValue=v;count=n;}}
public class Properties {public string GetString(string a,string b)=>b=="InputMaterials"?"iron,clay":"";public string GetString(string a)=>"";}
public class Block {public Properties Properties=new Properties();public string GetBlockName()=>"forge";}
public struct BlockValue {public Block Block;}public class WorkstationData {}
public static class RebirthCamperCraftingStation {public static bool TryResolve(ItemStack i,out BlockValue b,out WorkstationData c){b=new BlockValue{Block=new Block()};c=new WorkstationData();return true;}}
public class Writer:BinaryWriter {public Writer():base(new MemoryStream()){}public void SetBaseStream(Stream s){OutStream=s;}protected override void Dispose(bool d){Flush();}}
public class Reader:BinaryReader {public Reader():base(new MemoryStream()){}private Stream stream;public void SetBaseStream(Stream s){stream=s;}public override ushort ReadUInt16(){return new BinaryReader(stream,System.Text.Encoding.UTF8,true).ReadUInt16();}public override int ReadInt32(){return new BinaryReader(stream,System.Text.Encoding.UTF8,true).ReadInt32();}public override ulong ReadUInt64(){return new BinaryReader(stream,System.Text.Encoding.UTF8,true).ReadUInt64();}public override byte ReadByte(){return new BinaryReader(stream,System.Text.Encoding.UTF8,true).ReadByte();}protected override void Dispose(bool d){} }
public class WriterPool{public Writer AllocSync(bool b)=>new Writer();}public class ReaderPool{public Reader AllocSync(bool b)=>new Reader();}public static class MemoryPools{public static WriterPool poolBinaryWriter=new WriterPool();public static ReaderPool poolBinaryReader=new ReaderPool();}
public class Receipt {public ItemStack CraftedItemStack;}
public class TileEntityWorkstation {public int InputSlotCount=3;public string[] MaterialNames={"iron","clay"};public ItemStack[] Tools=Cells(1),Fuel=Cells(1),Input=Cells(5),Output=Cells(1),lastInput=Cells(3);public object[] Queue=new object[0];public float[] currentMeltTimesLeft=new float[3];public List<Receipt> CraftCompleteList=new List<Receipt>();public ulong lastTickTime;
static ItemStack[] Cells(int n)=>Enumerable.Range(0,n).Select(i=>new ItemStack(new ItemValue(),0)).ToArray();
public void write(Writer w,StreamModeWrite mode){w.Write((ushort)19);w.Write(0);w.Write(0);w.Write(0);w.Write((ulong)0);w.Write((byte)50);foreach(var group in new[]{Tools,Fuel,Input,Output,lastInput,CraftCompleteList.Select(x=>x.CraftedItemStack).ToArray()}){w.Write((byte)group.Length);foreach(var cell in group){w.Write((ushort)Math.Min(cell.count,65535));if(cell.count>0)w.Write(cell.itemValue.type);}}}
public void read(Reader r,StreamModeRead mode){r.ReadUInt16();r.ReadInt32();r.ReadInt32();r.ReadInt32();r.ReadUInt64();r.ReadByte();var groups=new ItemStack[6][];for(int g=0;g<6;g++){int n=r.ReadByte();groups[g]=Cells(n);for(int i=0;i<n;i++){int count=r.ReadUInt16();groups[g][i]=new ItemStack(new ItemValue{type=count>0?r.ReadInt32():0},count);}}Tools=groups[0];Fuel=groups[1];Input=groups[2];Output=groups[3];lastInput=groups[4];CraftCompleteList=groups[5].Select(x=>new Receipt{CraftedItemStack=x}).ToList();}}
public class RebirthCamperStationState:TileEntityWorkstation {public Guid InstallationId;public BlockValue InstalledBlock=new BlockValue{Block=new Block()};public long Revision;public RebirthCamperStationState(Guid id,ItemStack item){InstallationId=id;Input[3].itemValue.type=11;Input[4].itemValue.type=12;}public void RestoreRevision(long n){Revision=n;}}
public static class MoltenSnapshotChecks {static void Check(bool b,string s){if(!b)throw new Exception(s);}public static void Run(){var id=Guid.NewGuid();var item=new ItemStack(new ItemValue{type=9},1);var state=new RebirthCamperStationState(id,item){Revision=7,lastTickTime=999};state.Input[3].count=123456;state.Input[4].count=0;state.Input[0]=new ItemStack(new ItemValue{type=2},4);
var bytes=RebirthCamperStationSnapshot.Capture(id,state);var restored=RebirthCamperStationSnapshot.Restore(id,item,bytes);Check(restored.Input[3].count==123456&&restored.Input[3].itemValue.type==11&&restored.Input[4].count==0&&restored.Input[4].itemValue.type==12&&restored.Input[0].count==4&&restored.Revision==7,"exact counters/native zero identity");
var twice=RebirthCamperStationSnapshot.Restore(id,item,RebirthCamperStationSnapshot.Capture(id,restored));Check(twice.Input[3].count==123456&&twice.Input[4].count==0,"reload duplicates/loses credits");var address=new RebirthCamperStationAddress(Guid.NewGuid(),id);var portable=RebirthCamperPortableStation.Capture(item,state,address);Check(RebirthCamperPortableStation.TryRestore(portable,out var placed)&&placed.Input[3].count==123456&&placed.Input[4].itemValue.type==12&&placed.lastTickTime==0&&state.lastTickTime==999,"portable exact counters paused");var old=RebirthCamperPortableStation.Capture(item,state);Check(RebirthCamperPortableStation.TryRestore(old,out placed)&&placed.Input[3].count==123456,"legacy RSP1 native counter frame");Console.WriteLine("PASS actual RCS4 capture/restore + RSP1/RSP2 portability: 123456 units, typed zero, repeated reload, physical stock, revision and item clock. Native workstation serialization explicitly doubled with UInt16 clamp/zero omission.");}}
"@
foreach($file in @('RebirthCamperStationSnapshot','RebirthCamperStationAddress','RebirthCamperPortableStation')){$code+=[regex]::Replace([IO.File]::ReadAllText((Join-Path $root "Scripts/Vehicles/Camper/$file.cs")),'(?m)^using [^;]+;\r?\n','')+"`n"}
Add-Type -TypeDefinition $code
[MoltenSnapshotChecks]::Run()